/* Пошаговый гайд для учебной базы: каждый раздел, каждая секция и кнопка с подсветкой. */
'use strict';

/* поиск карточки или панели по заголовку */
const trCard = (title) => () => $$('#main .card, #main .panel, #main details.card').find(c => {
  const h = c.querySelector('h2, h3, summary');
  return h && h.textContent.trim().startsWith(title);
}) || null;

